class Solution:
    def search(self, nums: list[int], target: int) -> int:
        left, right = 0, len(nums)        # [left, right)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid                # 注意是 mid，不是 mid - 1
        return -1
```

关键说明：
