        if not self.s_out:
            while self.s_in:
                self.s_out.append(self.s_in.pop())
        return self.s_out.pop()

    def peek(self):
        ans = self.pop()
        self.s_out.append(ans)
        return ans

    def empty(self):
        return not self.s_in and not self.s_out
