class Solution:
    def partition(self, s):
        ans, path = [], []
        def is_palin(t): return t == t[::-1]
        def backtrack(start):
            if start == len(s):
                ans.append(path[:]); return
            for i in range(start, len(s)):
                seg = s[start:i+1]
                if is_palin(seg):
                    path.append(seg)
                    backtrack(i + 1)
                    path.pop()
        backtrack(0)
        return ans
