class Solution:
    def solveNQueens(self, n):
        board = [['.'] * n for _ in range(n)]
        ans = []

        def valid(row, col):
            # 同列
            for i in range(row):
                if board[i][col] == 'Q': return False
            # 左上对角
            i, j = row - 1, col - 1
            while i >= 0 and j >= 0:
                if board[i][j] == 'Q': return False
                i -= 1; j -= 1
            # 右上对角
            i, j = row - 1, col + 1
            while i >= 0 and j < n:
                if board[i][j] == 'Q': return False
                i -= 1; j += 1
            return True

        def backtrack(row):
            if row == n:
                ans.append([''.join(r) for r in board]); return
            for col in range(n):
                if valid(row, col):
                    board[row][col] = 'Q'
                    backtrack(row + 1)
                    board[row][col] = '.'
        backtrack(0)
        return ans
```

