class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        if len(s) < len(p):
            return []
        need, cur = [0] * 26, [0] * 26
        for c in p:
            need[ord(c) - ord('a')] += 1
        for c in s[:len(p)]:
            cur[ord(c) - ord('a')] += 1
        ans = [0] if cur == need else []
        for i in range(len(p), len(s)):
            cur[ord(s[i]) - ord('a')] += 1
            cur[ord(s[i - len(p)]) - ord('a')] -= 1
            if cur == need:
                ans.append(i - len(p) + 1)
        return ans
```

关键说明：
- 维护长度为 len(p) 的定长滑动窗口与长度为 26 的频次数组
- 每次右移一格同步增删进出窗口的字符计数并比对 cur == need

